<template>
  <section class="page"><header class="page-heading"><div><p class="eyebrow">Management information</p><h1>Reports</h1><p class="subtitle">Review asset inventory, assignment, maintenance, and disposal activity.</p></div><button class="primary-button" type="button" @click="downloadReport">Download Report</button></header><section class="stats"><article><span>Total assets</span><strong>{{ assets.length }}</strong><small>Across all stations</small></article><article><span>Assigned assets</span><strong>{{ assigned }}</strong><small>{{ Math.round((assigned / assets.length) * 100) }}% of inventory</small></article><article><span>Pending disposal</span><strong>2</strong><small>Require approval</small></article><article><span>Available assets</span><strong>{{ available }}</strong><small>Ready for assignment</small></article></section><div class="report-grid"><section class="panel"><div class="panel-heading"><h2>Assets by status</h2><span>Current inventory</span></div><div v-for="item in statusSummary" :key="item.label" class="bar-row"><div><span>{{ item.label }}</span><strong>{{ item.value }}</strong></div><div class="bar"><i :style="{ width: `${(item.value / assets.length) * 100}%` }"></i></div></div></section><section class="panel"><div class="panel-heading"><h2>Assets by station</h2><span>Distribution</span></div><div v-for="item in stationSummary" :key="item.label" class="station-row"><span>{{ item.label }}</span><strong>{{ item.value }} assets</strong></div></section></div><section class="panel table-panel"><div class="panel-heading"><h2>Recent report activity</h2><select v-model="reportType"><option>All activity</option><option>Inventory</option><option>Disposal</option><option>Maintenance</option></select></div><table><thead><tr><th>Report</th><th>Generated By</th><th>Date</th><th>Records</th><th>Status</th></tr></thead><tbody><tr v-for="report in reports" :key="report.name"><td><strong>{{ report.name }}</strong></td><td>{{ report.user }}</td><td>{{ report.date }}</td><td>{{ report.records }}</td><td><span class="status">Ready</span></td></tr></tbody></table></section></section>
</template>

<script setup>
import { computed, ref } from 'vue';
import { assets } from '@/data/assets';
const reportType = ref('All activity');
const assigned = computed(() => assets.filter((asset) => asset.status === 'Assigned').length); const available = computed(() => assets.filter((asset) => asset.status === 'Available').length);
const statusSummary = computed(() => ['Assigned', 'Available', 'Under Maintenance', 'Pending Disposal'].map((label) => ({ label, value: assets.filter((asset) => asset.status === label).length })));
const stationSummary = computed(() => [...new Set(assets.map((asset) => asset.station))].map((label) => ({ label, value: assets.filter((asset) => asset.station === label).length })).sort((a, b) => b.value - a.value).slice(0, 5));
const reports = [{ name: 'Asset Inventory Summary', user: 'Digna Andrea', date: '15/09/2026', records: assets.length }, { name: 'Disposal Requests Register', user: 'Digna Andrea', date: '02/09/2026', records: 2 }, { name: 'Maintenance Activity Report', user: 'J. Mushi', date: '01/09/2026', records: 3 }];
function downloadReport() { window.print(); }
</script>

